const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const afghanistan = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Afghanistan'))
    .geometry();

  const date1_start = '2017-02-01';
  const date1_end = '2017-02-28';
  const date2_start = '2018-02-01';
  const date2_end = '2018-02-28';

  const collectionName = 'MODIS/061/MOD11A1';
  const lstBand = 'LST_Day_1km';

  // Function to process images: mask clouds, scale, and convert to Celsius
  function processLST(image) {
    const qa = image.select('QC_Day');
    // Bits 0-1: Mandatory QA flags. 00 = Good quality.
    const goodQuality = qa.bitwiseAnd(3).eq(0);
    const lst = image.select(lstBand)
                     .updateMask(goodQuality)
                     .multiply(0.02) // Scale factor
                     .subtract(273.15); // Kelvin to Celsius
    return lst.copyProperties(image, ['system:time_start']);
  }

  // 2. Data Acquisition & Check
  const col1 = ee.ImageCollection(collectionName)
    .filterDate(date1_start, date1_end)
    .filterBounds(afghanistan)
    .map(processLST);

  const col2 = ee.ImageCollection(collectionName)
    .filterDate(date2_start, date2_end)
    .filterBounds(afghanistan)
    .map(processLST);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count 2017: ${size1}`);
    console.log(`Image count 2018: ${size2}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }

  // 3. Processing
  const image1 = col1.median().rename('lst');
  const image2 = col2.median().rename('lst');

  const scale = 1000; // Use a coarse scale for a large area

  const stats1 = image1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: afghanistan,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: afghanistan,
    scale: scale,
    maxPixels: 1e9
  });

  const [data1, data2] = await Promise.all([stats1.getInfo(), stats2.getInfo()]);

  const mean1 = data1.lst_mean;
  const count1 = data1.lst_count;
  const mean2 = data2.lst_mean;
  const count2 = data2.lst_count;

  console.log(`Feb 2017 Imgs: ${size1}, Mean LST: ${mean1 ? mean1.toFixed(2) : 'N/A'} C, Valid Pixels: ${count1}`);
  console.log(`Feb 2018 Imgs: ${size2}, Mean LST: ${mean2 ? mean2.toFixed(2) : 'N/A'} C, Valid Pixels: ${count2}`);

  // 4. Validation
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after cloud masking for one or both periods.");
    console.log("C2");
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation resulted in null or NaN.");
    console.log("C3");
    return;
  }

  // 5. Final Answer
  if (mean2 > mean1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error("An error occurred during Earth Engine initialization or analysis.");
    console.error(e);
    console.log("D");
  }
}

initEE();
